        content: "output मधील मजकूर व संख्या स्थिर रुंदीच्या स्तंभात राहण्यासाठी f-string मध्ये संरेखन चिन्हे वापरतात. {x:>10} मजकूर उजवीकडे, {x:<10} डावीकडे, {x:^10} मध्यभागी ठेवतो; 10 ही एकूण रुंदी.\n{:>10} चा उपयोग संख्या स्तंभात उजवी करून एके-दांडी मांडणीसाठी — पावती, बिल, अहवाल यांचा नेमका आकार. आकडे उजवी केल्यास नेहमी शेवटच्या अंकाची रांग सरळ दिसते.\n{:*^20} किंवा {:-<20} मधील * किंवा - हे fill चिन्ह — उरलेल्या जागा त्या चिन्हाने भरतात; शीर्षकांच्या सजावटीसाठी उपयोगी. रचना {value:fill-char alignment width} असते.\n{.2f}, {,}, {:.1%} हे आधीच शिकलेले नियम संरेखनासोबत लागतात: f\"{total:>10,.2f}\" मधून संख्येला कॉमा व दशांश यांसह उजवी रांग मिळते.\nएकाच ओळीत अनेक {} ठिकाणे असू शकतात; प्रत्येक {} चा स्वतःचा नियम (spec) असतो. f\"{a:>5} | {b:<10} | {c:^8}\" असे स्तंभ तयार करता येतात.\nचुका टाळा: रुंदी कमी पडली तर संख्या तशीच लांब दिसते, कापली जात नाही; रुंदी ही किमान जागा आहे, कमाल नव्हे.\nसराव: 42.567 ला रुंदी 10, दशांश 2 आणि कॉमा देऊन output करा — f\"{42.567:>10,.2f}\"; शीर्षक center ने सजवा; रुंदी बदलून रांग कशी बदलते ते पहा.",
