        content: "f-string मध्ये मजकुरातच } किंवा { दाखवायचे असल्यास दुहेरी लिहावे लागते: {{ आणि }}. print(f\"प्रगती: {{100}}%\") मधून प्रगत: {100}% दिसते — एकेरी नियम अनोखा.\nबहुओळी f-string: f\"\"\"...\"\"\" च्या आत अनेक ओळी लिहिता येतात; प्रत्येक ओळीलाच {} मधील expression मूल्यात बदलते. अहवाल, संदेश, कविता — असा मजकूर एकाच block मध्ये तयार होतो.\nvariable चे नाव मजकुरात बघायचे असल्यास f\"{वेल्यु = }\" ही शॉर्टकट रचना वापरता येते — debugging दरम्यान नाव आणि मूल्य एकत्र दाखवते.\nदिनांक व गणिती मूल्ये f-string मध्ये सहज मिसळतात: f\"आज {date_field}\" किंवा f\"एकूण: {math.pi:.4f}\" — import केलेला module expression म्हणून वापरला जातो.\nसूक्ष्म नियम: { } च्या आत असलेला backslash प्रकार — f-string च्या जुन्या आवृत्त्यांमध्ये टाळा; जुन्या Python वर चालवताना expression मध्ये backslash नसेल असे लिहा.\nआत्ताच्या उदाहरणांमध्ये आपण labels, चिन्हे आणि आकडे अशा गोष्टी वेगवेगळ्या thor — प्रत्येक योग्य ठिकाणी ठेवणे output ची गुरुकिल्ली.\nसराव: \"100% हजर\" हे वाक्य {{ }} च्या साहाय्याने f-string मध्ये लिहा; बहुओळी f-string तयार करा; debugging साठी {name = } चा वापर करा.",
