        content: "या string formatting धड्यात f-string हा मुख्य विषय ठरला — f\"...\" मधील {} मध्ये कोणतीही expression बसते; expression चे मूल्य form मध्ये विरघळते; अर्थ मजकुरात nimia.\nनियंत्रणांची त्रयी — रुंदी (width), संरेखन (< > ^), दशांश (.2f) — प्रत्येक {} च्या आत {value:spec} अशा रूपात जोडली जाते; कॉमा , हे सहस्रक विभाजक.\nकारण जुने मार्ग %-formatting आणि str.format() हे वाचताना कळणे आवश्यक; लिहिताना मात्र f-string ही शिफारस. दोन्ही समान नियमांवर चालतात.\nकुरळे कोष्टक दाखवण्यासाठी {{ }} दुहेरी; बहुओळी f-string एकाच block मध्ये संपूर्ण मजकूर तयार करतात; {var = } debugging ला मदत करते.\nव्यवहारात f-string अहवाल, पावती, बिल, फॉर्म संदेश यांचे भाषांतर करतो — मध्ये वास्तविक data थेट मजकुरात मिसळतो.\nस्वतःला विचारा: f\"{a}{b}\" आणि a + b यात फरक? रुंदी किमान का असते? दशांश नियम लिहायला विसरल्यास output कसे दिसते? प्रत्येक उत्तर कोडमध्ये तपासून पडताळा.",
