        content: "फाइल वाचण्यापूर्वी ती आहे का ते तपासणे ही सुरक्षित सवय आहे — FileNotFoundError टाळण्याचा सोपा मार्ग. os.path.exists(path) ही तयार तपासणी True किंवा False परत करते.\nimport os आणि os.path.isfile(\"notes.txt\") — only फाइल असल्यास True; os.path.isdir(\"data\") फक्त निर्देशिकेसाठी. दिशा आणि फाइल यांचा भेद हा तपासणीमध्ये समजतो.\nपथ (path) म्हणजे फाइल कुठे आहे ते सांगणारा मार्ग — पूर्ण पथ C:\\Users\\अनिकेत\\notes.txt किंवा फक्त notes.txt हा एका folder मधला. os.path.join(\"data\", \"class5.txt\") ने दोन भाग योग्य विभाजकासह जोडतात.\nवापर: if os.path.exists(\"marks.txt\"): read नाहीतर print(\"फाइल नाही\") — खोटा data अडवण्यापूर्वी program स्वतःच तपासणी करतो. हीच सवय फॉर्म व data प्रणालींमध्ये व्यावसायिक मानली जाते.\nfile handle वाचन स्वतः होत नाही — open with करताना exception येतो; त्यामुळे try/except मागील धड्यात शिकलो ते येथे दोन्ही एकत्र करता येते: os.path.exists सोबत try/except.\nचेतावणी: os.path.exists खोटे देऊ शकतो जर path चुकीचा असेल किंवा entries गहाळ असतील; म्हणून path लिहिताना नाव व folder चे capital-लहान अक्षरे तपासा.\nसराव: तुमच्या फोटोंच्या फोल्डरसाठी os.path.isfile व isdir तपासा; os.path.join ने एक मार्ग तयार करा; exists खोटे असल्यास मजकूर output करा.",
