        content: "फाइलमध्ये अनेकdata एका ओळीत कॉमांनी विभागलेले असतात — अशा रचनेला CSV (comma separated values) म्हणतात; Excel, शाळा reकॉर्ड, दुकानाची यादी अशा रूपात मिळतात.\nलिहिताना प्रत्येक ओळ कॉमा व \n ने जोडली: \"अनिकेत,80,85\n\" — नाव, गणित गुण, विज्ञान गुण; वाचताना line.strip() करून line.split(\",\") ने भाग वेगळे करतात.\n\"80,85\" अशा मजकुरांतून int(n) ने खऱ्या संख्या तयार होतात; मग math + science ची बेरीज करून output \"अनिकेत: 165\" दिसते. फाइल म्हणजे data साठवण, कोड तो वाचून गणना करतो.\nअनेक ओळींसाठी for line in f: हे लूप सर्व गुणांची बेरीज हाताळते — accumulator मागील धड्यातीलच; फाइल + loop + split हा मिलाफ हा एक चांगला data pipeline.\nCSV वाचताना जागा तपासा — \"अनिकेत, 80, 85\" मध्ये कॉमानंतर जागा असल्यास int(\" 80\") अडते; म्हणून int(part.strip()) किंवा part नीट स्वच्छ करून वापरा.\nसराव: तुमच्या पाच मित्रांच्या गुणांचा CSV लिहा आणि प्रत्येकाची बेरीज प्रत्येक ओळीसाठी output करा; कॉमानंतर जागा टाकून स्ट्रिपचा फरक पहा.",
