        content: "या files धड्यात open(path, mode) हे प्रवेशद्वार ठाम झाले — \"w\" पुसून लिहायला, \"a\" जोडायला, \"x\" नवीन बनवायला, \"r\" वाचायला. with ... as f ही रचना फाइल आपोआप बंद करते.\nवाचण्याचे चार मार्ग शिकलो: f.read() संपूर्ण, for line in f ओळ-ओळ, f.read().splitlines() यादीत, आणि CSV साठी split ने भाग — प्रत्येकाचा उपयोग वेगळा.\nos.path.exists, os.path.isfile, os.path.join यांनी फाइल अस्तित्व आणि पथ व्यवस्थापन सोपे झाले; try/except ने गहाळ फाइल सुरक्षित हाताळली.\nफाइलमधून वाचलेला मजकूर अजून string असतो — int() किंवा float() ने संख्येत बदलल्याशिवाय गणित शक्य नाही; मराठीसाठी encoding=\"utf-8\" लिहिताना-वाचताना समान ठेवा.\nफाइल + loop + split हा मिलाफ data pipeline चा पाया आहे — वाचा, प्रक्रिया करा, सारांश द्या ही रचना सर्वत्र लागू.\nस्वतःला विचारा: \"w\" आणि \"a\" फरक काय? फाइल नसल्यास कोणती error येते? रिकामी ओळ कशी हाताळाल? प्रत्येक उत्तर छोट्या कोडमध्ये तपासून पडताळा.",
