        content: "json.dump आणि json.load या फाइल-विशेष क्रिया आहेत — या मागील files धड्यातील open च्या जोडीने वापरतात. settings.json मध्ये एक dict साठवून पुन्हा वाचण्याचा प्रवास पाहू.\njson.dump(settings, f) फाइल handle ला मजकूर लिहितो; json.load(f) तीच फाइल उघडून Python रचना बनवतो. dumps/loads मजकुरासाठी, dump/load फाइलसाठी — चार नावांची ही जोडपी कधीही मिसळू नयेत.\nफाइल मध्ये मराठी अक्षरे हवी असल्यास dump करताना ensure_ascii=False; load करताना फाइलची encoding utf-8 मध्ये साठवा म्हणजे मजकूर साफ परत येतो.\nअनेकdata साठवण्यासाठी फाइलमध्ये list of dicts ठेवता येते — books = [{\"शीर्षक\": ...}, ...]; load केल्यावर for b in data: print(b[\"शीर्षक\"]) ने प्रत्येक घटक क्रमाने.\nही रचना संपर्क, नोंदी, इतिहास, library — नेहमीची साठवण आहे; program बंद झाल्यावर data हरवत नाही, फाइलवर टिकतो.\nचेतावणी: load करताना फाइल खराब JSON असल्यास json.JSONDecodeError येतो; try/except ने तो हाताळून मजकूर वापरकर्त्याला दाखवता येतो — program सुरू राहतो.\nसराव: एक library फाइल बनवा — तीन पुस्तके list of dicts स्वरूपात; पुन्हा load करून प्रत्येक पुस्तकाचे शीर्षक व लेखक output करा.",
