        content: "तारखेला वाचनीय मजकुरात बदलणे हे रिपोर्ट व मेसेजसाठी आवश्यक — strftime मध्ये % चिन्हांसह कोड देतात: %d दिवस, %m महिना, %Y वर्ष, %H तास, %M मिनिट, %S सेकंद.\nमराठी शैली: \"%d/%m/%Y\" देते 15/09/2026; \"%d %B %Y\" देते 15 September 2026 म्हणजे संपूर्ण महिन्याचे नाव; \"%A\" संपूर्ण आठवड्याचे नाव. %I तास 12 तासांत आणि %p सकाळ/संध्याकाळ देतो.\nप्रत्येक % च्या नंतर अक्षराचा अर्थ वेगळा — capital %Y संपूर्ण वर्ष, %y केवळ शेवटचे दोन; %H 00-23, %I 01-12. .strftime(\"%Y-%m-%d %H:%M\") हा ISO सारखा क्रम माहितीत लोकप्रिय.\nअसा मजकूर फाइल नावांसाठी इष्ट — report_2026-09-15.csv सारखे नाव तारखेवरून निर्माण करता येते; date व files दोन्ही एकत्र येतात.\nफाइल व looping मध्ये प्रत्येक दिवस वेगळ्या फाइलवर — filename = f\"log_{today.strftime('%Y%m%d')}.txt\" ही व्यावहारिक रचना — दिवसानुसार ठेवल्या नोंदी मागे-पुढे शोधणे सोपे.\nकाळजी: %Y मोठे अक्षर चालते, %y लहान वेगळे; मिनिट %M आणि महिना %m एकमेकांत बदलू नका — दोन्ही दिसायला सारखे पण अर्थ वेगळा.\nसराव: तारीख वेळ तीन मार्गांनी strftime दाखवा — दिवस/महिना/वर्ष, संपूर्ण महिना व आठवड्याचे नाव, आणि 12-तास स्वरूप; निरनिराळे पर्याय तपासा.",
