        content: "वापरकर्त्याकडून मिळणारी तारीख सामान्यतः मजकूर असते — \"19/09/2026\" अशी. अशी string तारखेच्या रूपात (datetime object) बदलण्यासाठी strptime वापरतात; strftime च्या उलट दिशा.\nखरे उदाहरण: date_str = \"19/09/2026\" ला datetime.strptime(date_str, \"%d/%m/%Y\") देतो; दुसरा वेळ format मध्ये input मध्ये कसा आहे ते सांगितलेले असते — format जुळले नाही तर ValueError येतो.\nमनुष्यप्राण्याशी बोलताना वेळ फॉरमॅट्स बदलतात — \"2026-09-19\", \"Sept 19, 2026\", \"19/09\" — प्रत्येकांना वेगळा format string आवश्यक; त्यामुळे वापरकर्त्याकडून format स्पष्टपणे विचारणे उत्तम.\nवापर: वापरकर्त्याने भरलेल्या तारखा एकत्र आणून फरक काढणे — दोन्ही strptime ने parse करून timedelta मिळवतो; असे स्पष्ट युक्त्या तारीख शहाणपणाने ठरतात.\nफाइलमधून तारखा मिळाल्या — रजिस्ट्ररच्या फाइलमधील ओळी \"शिक्षकाचा जन्म\" parse करून वय काढता येते; मजकूर तारीख कधीकधी वेगवेगळ्या स्वरूपात असते हे लक्षात ठेवा.\nचेतावणी: format व input यांची जुळणी नेमकेपणे हवी — जागा, डॅश वा स्लॅश समान असले पाहिजेत; नाही तर ValueError येतो.\nसराव: तुमचा जन्मदिवस string मध्ये साठवा; strptime ने object बनवा; त्यातून आजपर्यंतचे उरलेले दिवस timedelta ने मोजा; output मध्ये दिवस संख्या दाखवा.",
